var humidity = msg.payload[1] / 10;
var api = msg.payload[2]; // Misalnya, distance sekarang menjadi API
var gas = msg.payload[3]; // Nilai gas berasal dari payload indeks ke-3
var unixtime = Math.round(Date.now() / 1000);

if (msg.payload != "") {
    msg.topic = "INSERT INTO monitoring(temperature, humidity, api, gas, unixtime) VALUES(" + temperature + "," + humidity + "," + api + "," + gas + "," + unixtime + ")";
    return msg;
}

msg.payload = {
    "chatId" : 6306126443,
    "type" : "message",
    "content" : "Monitoring Kebakaran dan Lingkungan"

};
return msg;

msg.topic = `
    SELECT 
        api AS latest_api, 
        gas AS latest_gas 
    FROM monitoring 
    ORDER BY id DESC 
    LIMIT 1;
`;
return msg;

// Validasi payload
if (!msg.payload || msg.payload.length === 0) {
    node.error("Data payload kosong atau tidak valid", msg);
    return null;
}

// Ambil nilai dari hasil query
var api = msg.payload[0].latest_api; // Ambil nilai API
var gas = msg.payload[0].latest_gas; // Ambil nilai GAS

// Dapatkan timestamp saat ini
var timestamp = new Date().toLocaleString(); // Format waktu lokal

// Inisialisasi pesan peringatan
var messageContent = "";

// Cek kondisi
if (api === 0) {
    messageContent += `Peringatan! Terjadi kebakaran!\n`;
}

if (gas === 0) {
    messageContent += `Peringatan! Terdeteksi gas berbahaya!\n`;
}

// Jika ada pesan yang perlu dikirimkan
if (messageContent !== "") {
    msg.payload = {
        "chatId": 6306126443,
        "type": "message",
        "content": `${messageContent}Waktu: ${timestamp}`
    };
    return msg;
}

// Jika tidak ada kondisi yang terpenuhi, jangan kirim pesan
return null;

msg.topic = `
    SELECT 
        temperature AS latest_temp, 
        humidity AS latest_hum 
    FROM monitoring 
    ORDER BY id DESC 
    LIMIT 1;
`;
return msg;

// Ambil data dari payload
var temperature = msg.payload[0].latest_temp;
var humidity = msg.payload[0].latest_hum;


// Kirim data ke masing-masing gauge
return [
    { payload: temperature }, // Untuk gauge temperature
    { payload: humidity }     // Untuk gauge humidity
];

// Ambil data dari payload
var api = msg.payload[0].latest_api;
var gas = msg.payload[0].latest_gas;

// Tentukan status berdasarkan nilai sensor
var apiStatus = api === 1 ? "Aman" : "Terdeteksi Kebakaran";
var gasStatus = gas === 1 ? "Aman" : "Terdeteksi Gas Berbahaya";

// Kirim data ke masing-masing gauge
return [
    { payload: apiStatus }, // Untuk gauge sensor api
    { payload: gasStatus }  // Untuk gauge sensor gas
];

var tanggal = parseInt(msg.payload/1000) - 25200;
flow.set('tanggal', tanggal);
msg.payload = tanggal;
return msg;

var waktu_awal = parseInt(msg.payload / 1000);
flow.set('waktu_awal', waktu_awal);
msg.payload = waktu_awal;
return msg;

var waktu_akhir = parseInt(msg.payload/1000);
flow.set('waktu_akhir', waktu_akhir);
msg.payload = waktu_akhir;
return msg;

var tanggal = flow.get('tanggal');
var waktu_awal = flow.get('waktu_awal');
var waktu_akhir = flow.get('waktu_akhir');

var start = tanggal+waktu_awal;
var end = tanggal+waktu_akhir;

msg.topic = "SELECT * FROM monitoring WHERE unixtime BETWEEN "+start+" AND "+end+";";
msg.payload = [tanggal,waktu_awal,waktu_akhir,start, end];
return msg;

// Pastikan msg.payload berisi array data
let array = msg.payload;

// Iterasi untuk memproses setiap elemen dalam array
array.forEach((data, index) => {
    // Konversi waktu Unix menjadi format lokal
    if (data.unixtime) {
        const date = new Date(data.unixtime * 1000);
        data.unixtime = date.toLocaleString('es-US', {
            timeZone: "Asia/Jakarta",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false
        });
    }

    // Tambahkan unit ke temperature dan humidity
    if (typeof data.temperature === "number") {
        data.temperature = data.temperature + " °C";
    }
    if (typeof data.humidity === "number") {
        data.humidity = data.humidity + " %";
    }

    // Tambahkan nomor urut
    data.number = index + 1;

    // Konversi nilai api ke status
    if (typeof data.api === "number") {
        data.api = data.api === 0 ? "Terdeteksi Kebakaran" : "Aman";
    }

    // Konversi nilai gas ke status
    if (typeof data.gas === "number") {
        data.gas = data.gas === 0 ? "Terdeteksi Gas Berbahaya" : "Aman";
    }
});

// Kembalikan array yang telah diproses
msg.payload = array;

return msg;

var fileLocation = flow.get('fileLocation');
msg.payload = fileLocation;
msg.filename = fileLocation;
return msg;

var tanggal = flow.get('tanggal');
var waktu_awal = flow.get('waktu_awal');
var waktu_akhir = flow.get('waktu_akhir');

var start = tanggal + waktu_awal;
var end = tanggal + waktu_akhir;

msg.topic = "SELECT * FROM monitoring WHERE unixtime BETWEEN " + start + " AND " + end + ";";

return msg;

// Membalik urutan data untuk memastikan urutan yang benar
var data = msg.payload.reverse();
var time = [];
var temperature = [];
var humidity = [];
var apiStatus = [];
var gasStatus = [];

for (var i = 0; i < msg.payload.length; i++) {
    // Format waktu
    time[i] = new Date(msg.payload[i].unixtime * 1000).toLocaleString('en-US', {
        timeZone: "Asia/Jakarta",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false
    });

    // Data lainnya
    temperature[i] = msg.payload[i].temperature;
    humidity[i] = msg.payload[i].humidity;

    // Status API (0 = Kebakaran, 1 = Aman)
    apiStatus[i] = msg.payload[i].api === 0 ? "Terdeteksi Kebakaran" : "Aman";

    // Status GAS (0 = Gas Berbahaya, 1 = Aman)
    gasStatus[i] = msg.payload[i].gas === 0 ? "Terdeteksi Gas Berbahaya" : "Aman";
}

// Header CSV
var csv = "REPORT MONITORING SENSOR \n";
csv += "time,temperature,humidity,api_status,gas_status\n";

// Isi data CSV
for (var j = msg.payload.length - 1; j >= 0; j--) {
    csv += time[j] + "," + temperature[j] + "," + humidity[j] + "," + apiStatus[j] + "," + gasStatus[j] + "\n";
}

// Menentukan payload dan direktori file
msg.payload = csv;
var basePath = "C:\Users\asus\Downloads";
var fileName = "data_export.csv";
msg.filename = basePath + fileName;
flow.set('fileLocation', basePath + fileName);

return msg;
